extension Int {
	func cubed() -> Int {
		return self * self * self
	}
}

extension String {
	func withPrefix(_ prefix: String) -> String {
		if self.hasPrefix(prefix) { return self }
		return "\(prefix)\(self)"
	}
}

extension String {
	var isLong: Bool {
		return count > 25
	}
}

extension Double {
	var isNegative: Bool {
		return self < 0
	}
}

extension Int {
	func clamped(min: Int, max: Int) -> Int {
		if (self > max) {
			return max
		} else if (self < min) {
			return min
		}
		return self
	}
}

extension String {
	func isUppercased() -> Bool {
		return self == self.uppercased()
	}
}

